public bool VisibleSignBtn(object signStatusID, object signer)
{
    // Xét trạng thái ký số nếu có: tráng thái 1,2 --> false
    if (signStatusID != null && signStatusID.ToString() != "")
    {
        int status = Convert.ToInt32(signStatusID);
        if (status == 1 || status == 2) // 1_pending or 2_success (đang đợi xác thực hoặc đã ký thì ko dc ký nữa)
            return false;
    }

    // ko định danh người ký --> false
    if (signer == null || signer.ToString() == "")
        return false;

    // Chưa login --> false
    if (WebGlobal.User == null)
        return false;

    // Định danh chính là mình thì ok cho ký --> True
    return signer.ToString().ToLower() == WebGlobal.User.UserName.ToLower();
}

