/// <summary>
/// Class viền Bootstrap 5 theo trạng thái ký
/// </summary>
public string GetSignBorderClass(object signStatusID)
{
    if (signStatusID == null || signStatusID.ToString() == "")
        return "border-secondary";

    switch (Convert.ToInt32(signStatusID))
    {
        case 1: return "border-warning";
        case 2: return "border-success";
        case 3:
        case 4: return "border-danger";
        default: return "border-secondary";
    }
}

